    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t batch, uint32_t reduceDim, uint32_t innerDim,
                               uint32_t usedCores)
    {
        batch_ = batch;
        reduceDim_ = reduceDim;
        innerDim_ = innerDim;
        usedCores_ = usedCores;

        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(x));
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t*>(y));

        pipe_.InitBuffer(inputQueue_, 1, PLANE_BYTES);
        pipe_.InitBuffer(maxBuf_, PLANE_BYTES);
        pipe_.InitBuffer(argBuf_, PLANE_BYTES);
        pipe_.InitBuffer(candidateBuf_, PLANE_BYTES);
        pipe_.InitBuffer(argI32Buf_, PLANE_BYTES);
        pipe_.InitBuffer(maskBuf_, MASK_WORKSPACE_BYTES);
    }

    __aicore__ inline void Process()
    {
        if (batch_ == 0 || reduceDim_ == 0 || innerDim_ == 0 || usedCores_ == 0) {
            return;
        }

        const uint32_t blockIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());
        if (blockIdx >= usedCores_) {
            return;
        }

        AscendC::LocalTensor<float> maxLocal = maxBuf_.Get<float>();
        AscendC::LocalTensor<float> argLocal = argBuf_.Get<float>();
        AscendC::LocalTensor<float> candidateLocal = candidateBuf_.Get<float>();
        AscendC::LocalTensor<int32_t> argI32Local = argI32Buf_.Get<int32_t>();
        AscendC::LocalTensor<uint8_t> maskLocal = maskBuf_.Get<uint8_t>();

        for (uint32_t b = blockIdx; b < batch_; b += usedCores_) {
            AscendC::Duplicate(maxLocal, -3.402823466e+38f, static_cast<int32_t>(COMPUTE_ELEMS));
            AscendC::Duplicate(argLocal, 0.0f, static_cast<int32_t>(COMPUTE_ELEMS));
            AscendC::Duplicate(candidateLocal, 0.0f, static_cast<int32_t>(COMPUTE_ELEMS));

            const uint64_t batchBase = static_cast<uint64_t>(b) *
                static_cast<uint64_t>(reduceDim_) * static_cast<uint64_t>(innerDim_);
            for (uint32_t r = 0; r < reduceDim_; ++r) {
                AscendC::LocalTensor<float> inputLocal = inputQueue_.AllocTensor<float>();
                const uint64_t rowOffset = batchBase +
                    static_cast<uint64_t>(r) * static_cast<uint64_t>(innerDim_);
                const AscendC::DataCopyExtParams copyParams(
                    static_cast<uint16_t>(1),
                    static_cast<uint32_t>(VALID_ROW_BYTES),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0));
                const AscendC::DataCopyPadExtParams<float> padParams(true, 0, 1, 0.0f);
                AscendC::DataCopyPad(inputLocal, xGm_[rowOffset], copyParams, padParams);
                inputQueue_.EnQue(inputLocal);
                inputLocal = inputQueue_.DeQue<float>();

                AscendC::Compare(maskLocal, inputLocal, maxLocal,
                                 AscendC::CMPMODE::GT, COMPUTE_ELEMS);
                AscendC::Select(maxLocal, maskLocal, inputLocal, maxLocal,
                                AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, COMPUTE_ELEMS);
                AscendC::Select(argLocal, maskLocal, candidateLocal, argLocal,
                                AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, COMPUTE_ELEMS);
                inputQueue_.FreeTensor(inputLocal);

                if (r + 1 < reduceDim_) {
                    AscendC::Adds(candidateLocal, candidateLocal, 1.0f,
                                  static_cast<int32_t>(COMPUTE_ELEMS));
                }
