            AscendC::Cast(argI32Local, argLocal, AscendC::RoundMode::CAST_TRUNC,
                          COMPUTE_ELEMS);
            const AscendC::TEventID eventId = pipe_.FetchEventID<AscendC::HardEvent::V_S>();
            AscendC::SetFlag<AscendC::HardEvent::V_S>(eventId);
            AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventId);

            const uint64_t outputBase = static_cast<uint64_t>(b) * static_cast<uint64_t>(innerDim_);
