    AscendC::TBuf<AscendC::TPosition::VECCALC> argBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> candidateBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> argI32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maskBuf_;
