#include "kernel_operator.h"

class KernelAveragePooling2dCustom {
public:
    __aicore__ inline KernelAveragePooling2dCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t n, uint32_t c,
                               uint32_t h_in, uint32_t w_in,
                               uint32_t h_out, uint32_t w_out,
                               uint32_t outputRowTasks, uint32_t validElems,
                               uint32_t computeElems, uint32_t outputRowElems)
    {
        this->n = n;
        this->c = c;
        this->hIn = h_in;
        this->wIn = w_in;
        this->hOut = h_out;
        this->wOut = w_out;
        this->outputRowTasks = outputRowTasks;
        this->validElems = validElems;
        this->computeElems = computeElems;
        this->outputRowElems = outputRowElems;

        xGm.SetGlobalBuffer((__gm__ float*)x);
        yGm.SetGlobalBuffer((__gm__ float*)y);

        pipe.InitBuffer(inputQueue, 1, 90112);
        pipe.InitBuffer(accumulatorBuf, 8192);
        pipe.InitBuffer(gatherOffsetsBuf, 768);
        pipe.InitBuffer(gatherTemporaryBuf, 768);
        pipe.InitBuffer(outputQueue, 1, 768);
    }

    __aicore__ inline void Process()
    {
        constexpr uint32_t KERNEL_SIZE = 11;
        constexpr uint32_t INPUT_PLANE_ELEMS = 2048;
        constexpr uint32_t GATHER_OFFSET_STEP_BYTES = KERNEL_SIZE * sizeof(float);
        constexpr float INV_KERNEL_AREA = 1.0f / 121.0f;

        const uint32_t bid = AscendC::GetBlockIdx();
        const uint32_t blockCount = AscendC::GetBlockNum();
        const uint32_t channelRows = c * hOut;
        const uint32_t inputChannelElems = hIn * wIn;

        for (uint32_t task = bid; task < outputRowTasks; task += blockCount) {
            const uint32_t ni = task / channelRows;
            const uint32_t channelRow = task % channelRows;
            const uint32_t ci = channelRow / hOut;
            const uint32_t oh = channelRow % hOut;

            AscendC::LocalTensor<float> inputLocal = inputQueue.AllocTensor<float>();
            const uint64_t inputChannelBase =
                (static_cast<uint64_t>(ni) * c + ci) * inputChannelElems;
            const uint64_t firstInputRow = inputChannelBase +
                static_cast<uint64_t>(oh * KERNEL_SIZE) * wIn;
            const uint32_t inputCopyBytes = validElems * static_cast<uint32_t>(sizeof(float));
            const AscendC::DataCopyExtParams inputCopyParams{
                static_cast<uint16_t>(KERNEL_SIZE), inputCopyBytes,
                static_cast<uint32_t>((wIn - validElems) * sizeof(float)), 0u, 0u};
            const AscendC::DataCopyPadExtParams<float> inputPadParams{true, 0u, 2u, 0.0f};
            AscendC::DataCopyPad(inputLocal, xGm[firstInputRow],
                                inputCopyParams, inputPadParams);
            inputQueue.EnQue(inputLocal);
            inputLocal = inputQueue.DeQue<float>();

            AscendC::LocalTensor<float> accumulator = accumulatorBuf.Get<float>();
            AscendC::Add(accumulator, inputLocal, inputLocal[INPUT_PLANE_ELEMS], computeElems);
#pragma unroll
            for (uint32_t r = 2; r < KERNEL_SIZE; ++r) {
                AscendC::Add(accumulator, accumulator,
                             inputLocal[r * INPUT_PLANE_ELEMS], computeElems);
            }

            AscendC::LocalTensor<float> outputLocal = outputQueue.AllocTensor<float>();
            AscendC::LocalTensor<int32_t> signedGatherOffsets = gatherOffsetsBuf.Get<int32_t>();
            AscendC::LocalTensor<uint32_t> gatherOffsets =
                signedGatherOffsets.ReinterpretCast<uint32_t>();
            AscendC::LocalTensor<float> gatherTemporary = gatherTemporaryBuf.Get<float>();
            for (uint32_t tap = 0; tap < KERNEL_SIZE; ++tap) {
                AscendC::ArithProgression<int32_t>(
                    signedGatherOffsets, static_cast<int32_t>(tap * sizeof(float)),
                    static_cast<int32_t>(GATHER_OFFSET_STEP_BYTES),
                    static_cast<int32_t>(outputRowElems));
                if (tap == 0) {
                    AscendC::Gather(outputLocal, accumulator, gatherOffsets, 0u,
                                    outputRowElems);
                } else {
                    AscendC::Gather(gatherTemporary, accumulator, gatherOffsets, 0u,
                                    outputRowElems);
                    AscendC::Add(outputLocal, outputLocal, gatherTemporary,
                                 static_cast<int32_t>(outputRowElems));
                }
            }
            AscendC::Muls(outputLocal, outputLocal, INV_KERNEL_AREA,
                          static_cast<int32_t>(outputRowElems));
            inputQueue.FreeTensor(inputLocal);
            outputQueue.EnQue(outputLocal);
            outputLocal = outputQueue.DeQue<float>();

            const uint64_t outputOffset = static_cast<uint64_t>(task) * wOut;
            const uint32_t outputCopyBytes = outputRowElems * static_cast<uint32_t>(sizeof(float));
            const AscendC::DataCopyExtParams outputCopyParams{
                static_cast<uint16_t>(1), outputCopyBytes, 0u, 0u, 0u};
            AscendC::DataCopyPad(yGm[outputOffset], outputLocal, outputCopyParams);
            outputQueue.FreeTensor(outputLocal);
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, 1> inputQueue;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> accumulatorBuf;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> gatherOffsetsBuf;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> gatherTemporaryBuf;
    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> outputQueue;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t n, c, hIn, wIn, hOut, wOut;
    uint32_t outputRowTasks, validElems, computeElems, outputRowElems;
};

extern "C" __global__ __aicore__ void average_pooling2d_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);

    KernelAveragePooling2dCustom op;
    op.Init(x, y,
            tiling_data.n, tiling_data.c,
            tiling_data.h_in, tiling_data.w_in,
            tiling_data.h_out, tiling_data.w_out,
            tiling_data.outputRowTasks, tiling_data.validElems,
            tiling_data.computeElems, tiling_data.outputRowElems);
    op.Process();
}

