                        int32_t wi0 = wstart;
                        int32_t wi1 = wstart + K;
                        if (wi0 < 0) wi0 = 0;
                        if (wi1 > static_cast<int32_t>(w_in)) wi1 = static_cast<int32_t>(w_in);

