#include "kernel_operator.h"

class KernelAveragePooling3dCustom {
public:
    __aicore__ inline KernelAveragePooling3dCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t n, uint32_t c,
                               uint32_t d_in, uint32_t h_in, uint32_t w_in,
                               uint32_t d_out, uint32_t h_out, uint32_t w_out,
                               uint32_t rows, uint32_t rowsPerBlock)
    {
        (void)n;
        (void)rowsPerBlock;
        this->c = c;
        this->d_in = d_in;
        this->h_in = h_in;
        this->w_in = w_in;
        this->d_out = d_out;
        this->h_out = h_out;
        this->w_out = w_out;
        this->rows = rows;

        xGm.SetGlobalBuffer((__gm__ float*)x);
        yGm.SetGlobalBuffer((__gm__ float*)y);
        pipe.InitBuffer(inputQueue, 1, 2304U * sizeof(float));
        pipe.InitBuffer(accumulatorBuffer, 256U * sizeof(float));
        pipe.InitBuffer(outputQueue, 1, 128U * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        constexpr uint32_t INPUT_WIDTH = 256U;
        constexpr uint32_t OUTPUT_WIDTH = 128U;
        constexpr float INV_KERNEL_VOLUME = 1.0f / 27.0f;

        const uint32_t coreId = AscendC::GetBlockIdx();
        const uint32_t coreCount = AscendC::GetBlockNum();
        if (coreId >= rows) {
            return;
        }

        const uint64_t hwIn = static_cast<uint64_t>(h_in) * w_in;
        const uint64_t dhwIn = static_cast<uint64_t>(d_in) * hwIn;

        for (uint32_t row = coreId; row < rows; row += coreCount) {
            uint32_t decoded = row;
            const uint32_t oh = decoded % h_out;
            decoded /= h_out;
            const uint32_t od = decoded % d_out;
            decoded /= d_out;
            const uint32_t ci = decoded % c;
            const uint32_t ni = decoded / c;

            const int32_t dStart = static_cast<int32_t>(od) * 2 - 1;
            const int32_t hStart = static_cast<int32_t>(oh) * 2 - 1;
            const uint32_t firstD = dStart < 0 ? 0U : static_cast<uint32_t>(dStart);
            const uint32_t firstH = hStart < 0 ? 0U : static_cast<uint32_t>(hStart);
            const uint32_t lastD = dStart + 3 > static_cast<int32_t>(d_in)
                                       ? d_in : static_cast<uint32_t>(dStart + 3);
            const uint32_t lastH = hStart + 3 > static_cast<int32_t>(h_in)
                                       ? h_in : static_cast<uint32_t>(hStart + 3);
            const uint32_t validD = lastD - firstD;
            const uint32_t validH = lastH - firstH;
            const uint32_t planeCount = validD * validH;

            AscendC::LocalTensor<float> inputLocal = inputQueue.AllocTensor<float>();
            const uint64_t ncBase = (static_cast<uint64_t>(ni) * c + ci) * dhwIn;
            const uint64_t inputOffset = ncBase + static_cast<uint64_t>(firstD) * hwIn +
                                         static_cast<uint64_t>(firstH) * w_in;
            const uint32_t rowBytes = INPUT_WIDTH * static_cast<uint32_t>(sizeof(float));
            const uint32_t blockBytes = validH * rowBytes;
            const uint32_t sourceStrideBytes = (h_in - validH) * rowBytes;
            const AscendC::DataCopyExtParams inputCopyParams{
                static_cast<uint16_t>(validD), blockBytes, sourceStrideBytes, 0U, 0U};
            const AscendC::DataCopyPadExtParams<float> noPadParams(false, 0U, 0U, 0.0f);
            AscendC::DataCopyPad(inputLocal, xGm[inputOffset], inputCopyParams, noPadParams);
            inputQueue.EnQue(inputLocal);
            inputLocal = inputQueue.DeQue<float>();

            AscendC::LocalTensor<float> accumulator = accumulatorBuffer.Get<float>();
            AscendC::DataCopy(accumulator, inputLocal, INPUT_WIDTH);
            for (uint32_t plane = 1U; plane < planeCount; ++plane) {
                AscendC::Add(accumulator, accumulator, inputLocal[plane * INPUT_WIDTH],
                             static_cast<int32_t>(INPUT_WIDTH));
            }

            const auto eventVToS = GetTPipePtr()->FetchEventID(AscendC::HardEvent::V_S);
            AscendC::SetFlag<AscendC::HardEvent::V_S>(eventVToS);
            AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventVToS);

            AscendC::LocalTensor<float> outputLocal = outputQueue.AllocTensor<float>();
            for (uint32_t ow = 0U; ow < OUTPUT_WIDTH; ++ow) {
                const uint32_t center = ow * 2U;
                float sum = accumulator.GetValue(center);
                if (center != 0U) {
                    sum += accumulator.GetValue(center - 1U);
                }
                if (center + 1U < INPUT_WIDTH) {
                    sum += accumulator.GetValue(center + 1U);
                }
                outputLocal.SetValue(ow, sum);
            }

            const auto eventSToV = GetTPipePtr()->FetchEventID(AscendC::HardEvent::S_V);
            AscendC::SetFlag<AscendC::HardEvent::S_V>(eventSToV);
            AscendC::WaitFlag<AscendC::HardEvent::S_V>(eventSToV);
            AscendC::Muls(outputLocal, outputLocal, INV_KERNEL_VOLUME,
                          static_cast<int32_t>(OUTPUT_WIDTH));

            inputQueue.FreeTensor(inputLocal);
            outputQueue.EnQue(outputLocal);
            outputLocal = outputQueue.DeQue<float>();
            const uint64_t outputOffset = static_cast<uint64_t>(row) * w_out;
            const AscendC::DataCopyExtParams outputCopyParams(
                1U, OUTPUT_WIDTH * static_cast<uint32_t>(sizeof(float)), 0U, 0U, 0U);
            AscendC::DataCopyPad(yGm[outputOffset], outputLocal, outputCopyParams);
            outputQueue.FreeTensor(outputLocal);
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accumulatorBuffer;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    uint32_t c, d_in, h_in, w_in, d_out, h_out, w_out, rows;
};

extern "C" __global__ __aicore__ void average_pooling3d_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);

    KernelAveragePooling3dCustom op;
    op.Init(x, y,
            tiling_data.n, tiling_data.c,
            tiling_data.d_in, tiling_data.h_in, tiling_data.w_in,
            tiling_data.d_out, tiling_data.h_out, tiling_data.w_out,
            tiling_data.rows, tiling_data.rowsPerBlock);
    op.Process();
}

