    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t n, uint32_t c,
                               uint32_t d_in, uint32_t h_in, uint32_t w_in,
                               uint32_t d_out, uint32_t h_out, uint32_t w_out,
                               uint32_t odTile, uint32_t ohTile,
                               uint32_t odTiles, uint32_t ohTiles, uint32_t totalTasks)
    {
        (void)n;
        this->c = c;
        this->d_in = d_in;
        this->h_in = h_in;
        this->w_in = w_in;
        this->d_out = d_out;
        this->h_out = h_out;
        this->w_out = w_out;
        this->odTile = odTile;
        this->ohTile = ohTile;
        this->odTiles = odTiles;
        this->ohTiles = ohTiles;
        this->totalTasks = totalTasks;

        xGm.SetGlobalBuffer((__gm__ float*)x);
        yGm.SetGlobalBuffer((__gm__ float*)y);
        pipe.InitBuffer(inputQueue, 1, 8448U * sizeof(float));
        pipe.InitBuffer(outputQueue, 1, 32768U * sizeof(float));
        pipe.InitBuffer(tapBuffer, 3U * 128U * sizeof(float));
        pipe.InitBuffer(widthSumBuffer, 128U * sizeof(float));
        pipe.InitBuffer(offsetBuffer, 3U * 128U * sizeof(uint32_t));
    }

    __aicore__ inline void Process()
    {
        constexpr uint32_t INPUT_WIDTH = 256U;
        constexpr uint32_t OUTPUT_WIDTH = 128U;
        constexpr float INV_KERNEL_VOLUME = 1.0f / 27.0f;

        const uint32_t coreId = AscendC::GetBlockIdx();
        const uint32_t coreCount = AscendC::GetBlockNum();
        if (coreId >= totalTasks) {
            return;
        }

        const uint64_t hwIn = static_cast<uint64_t>(h_in) * w_in;
        const uint64_t dhwIn = static_cast<uint64_t>(d_in) * hwIn;

        AscendC::LocalTensor<uint32_t> offsets = offsetBuffer.Get<uint32_t>();
        for (uint32_t ow = 0U; ow < OUTPUT_WIDTH; ++ow) {
            offsets.SetValue(ow, (ow == 0U ? 0U : (2U * ow - 1U)) * sizeof(float));
            offsets.SetValue(OUTPUT_WIDTH + ow, 2U * ow * sizeof(float));
            offsets.SetValue(2U * OUTPUT_WIDTH + ow, (2U * ow + 1U) * sizeof(float));
        }

        for (uint32_t task = coreId; task < totalTasks; task += coreCount) {
            uint32_t decoded = task;
            const uint32_t ohTileIndex = decoded % ohTiles;
            decoded /= ohTiles;
            const uint32_t odTileIndex = decoded % odTiles;
            decoded /= odTiles;
            const uint32_t ci = decoded % c;
            const uint32_t ni = decoded / c;

            const uint32_t odBase = odTileIndex * odTile;
            const uint32_t ohBase = ohTileIndex * ohTile;
            const uint32_t validOd = (odBase + odTile > d_out) ? d_out - odBase : odTile;
            const uint32_t validOh = (ohBase + ohTile > h_out) ? h_out - ohBase : ohTile;
            const int32_t dStart = static_cast<int32_t>(odBase) * 2 - 1;
            const int32_t hStart = static_cast<int32_t>(ohBase) * 2 - 1;
            const uint32_t firstD = dStart < 0 ? 0U : static_cast<uint32_t>(dStart);
            const uint32_t firstH = hStart < 0 ? 0U : static_cast<uint32_t>(hStart);
            const uint32_t dLimit = 2U * (odBase + validOd - 1U) + 2U;
            const uint32_t hLimit = 2U * (ohBase + validOh - 1U) + 2U;
            const uint32_t lastD = dLimit > d_in ? d_in : dLimit;
            const uint32_t lastH = hLimit > h_in ? h_in : hLimit;
            const uint32_t validHSpan = lastH - firstH;

            AscendC::LocalTensor<float> accumulator = outputQueue.AllocTensor<float>();
            AscendC::Duplicate(accumulator, 0.0f, static_cast<int32_t>(odTile * ohTile * OUTPUT_WIDTH));
            AscendC::LocalTensor<float> taps = tapBuffer.Get<float>();
            AscendC::LocalTensor<float> widthSum = widthSumBuffer.Get<float>();
            const uint64_t ncBase = (static_cast<uint64_t>(ni) * c + ci) * dhwIn;
            const uint32_t rowBytes = INPUT_WIDTH * static_cast<uint32_t>(sizeof(float));
            const AscendC::DataCopyPadExtParams<float> noPadParams(false, 0U, 0U, 0.0f);

            for (uint32_t inputD = firstD; inputD < lastD; ++inputD) {
                AscendC::LocalTensor<float> inputLocal = inputQueue.AllocTensor<float>();
                const uint64_t inputOffset = ncBase + static_cast<uint64_t>(inputD) * hwIn +
                                             static_cast<uint64_t>(firstH) * w_in;
                const uint32_t copyBytes = validHSpan * rowBytes;
                const AscendC::DataCopyExtParams inputCopyParams{
                    static_cast<uint16_t>(1U), copyBytes, 0U, 0U, 0U};
                AscendC::DataCopyPad(inputLocal, xGm[inputOffset], inputCopyParams, noPadParams);
                inputQueue.EnQue(inputLocal);
                inputLocal = inputQueue.DeQue<float>();

                for (uint32_t inputH = firstH; inputH < lastH; ++inputH) {
                    const uint32_t localRow = (inputH - firstH) * INPUT_WIDTH;
                    AscendC::Gather(taps, inputLocal[localRow], offsets, 0U, OUTPUT_WIDTH);
                    AscendC::Gather(taps[OUTPUT_WIDTH], inputLocal[localRow], offsets[OUTPUT_WIDTH],
                                    0U, OUTPUT_WIDTH);
                    AscendC::Gather(taps[2U * OUTPUT_WIDTH], inputLocal[localRow],
                                    offsets[2U * OUTPUT_WIDTH], 0U, OUTPUT_WIDTH);
                    AscendC::Duplicate(taps, 0.0f, 1);
                    AscendC::PipeBarrier<PIPE_V>();
                    AscendC::Add(widthSum, taps, taps[OUTPUT_WIDTH],
                                 static_cast<int32_t>(OUTPUT_WIDTH));
                    AscendC::PipeBarrier<PIPE_V>();
                    AscendC::Add(widthSum, widthSum, taps[2U * OUTPUT_WIDTH],
                                 static_cast<int32_t>(OUTPUT_WIDTH));

                    uint32_t odFirst = inputD / 2U;
                    uint32_t odLast = (inputD + 1U) / 2U;
                    uint32_t ohFirst = inputH / 2U;
                    uint32_t ohLast = (inputH + 1U) / 2U;
                    if (odFirst < odBase) odFirst = odBase;
                    if (ohFirst < ohBase) ohFirst = ohBase;
                    const uint32_t odEnd = odBase + validOd;
                    const uint32_t ohEnd = ohBase + validOh;
                    if (odLast >= odEnd) odLast = odEnd - 1U;
                    if (ohLast >= ohEnd) ohLast = ohEnd - 1U;
                    AscendC::PipeBarrier<PIPE_V>();
                    for (uint32_t od = odFirst; od <= odLast; ++od) {
                        for (uint32_t oh = ohFirst; oh <= ohLast; ++oh) {
                            const uint32_t rowOffset =
                                ((od - odBase) * ohTile + (oh - ohBase)) * OUTPUT_WIDTH;
                            AscendC::Add(accumulator[rowOffset], accumulator[rowOffset], widthSum,
                                         static_cast<int32_t>(OUTPUT_WIDTH));
                        }
                    }
                }
                inputQueue.FreeTensor(inputLocal);
            }

            AscendC::Muls(accumulator, accumulator, INV_KERNEL_VOLUME,
                          static_cast<int32_t>(odTile * ohTile * OUTPUT_WIDTH));
            outputQueue.EnQue(accumulator);
            accumulator = outputQueue.DeQue<float>();
            const uint64_t outputOffset =
                ((((static_cast<uint64_t>(ni) * c + ci) * d_out + odBase) * h_out + ohBase) * w_out);
            const uint32_t outputBlockBytes = validOh * OUTPUT_WIDTH * static_cast<uint32_t>(sizeof(float));
            const uint32_t outputDstStrideBytes =
                (h_out - validOh) * OUTPUT_WIDTH * static_cast<uint32_t>(sizeof(float));
            const AscendC::DataCopyExtParams outputCopyParams(
                static_cast<uint16_t>(validOd), outputBlockBytes, 0U, outputDstStrideBytes, 0U);
            AscendC::DataCopyPad(yGm[outputOffset], accumulator, outputCopyParams);
            outputQueue.FreeTensor(accumulator);
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tapBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> widthSumBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBuffer;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    uint32_t c, d_in, h_in, w_in, d_out, h_out, w_out;
    uint32_t odTile, ohTile, odTiles, ohTiles, totalTasks;
};

extern "C" __global__ __aicore__ void average_pooling3d_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);

    KernelAveragePooling3dCustom op;
    op.Init(x, y,
            tiling_data.n, tiling_data.c,
            tiling_data.d_in, tiling_data.h_in, tiling_data.w_in,
            tiling_data.d_out, tiling_data.h_out, tiling_data.w_out,
            tiling_data.odTile, tiling_data.ohTile,
            tiling_data.odTiles, tiling_data.ohTiles, tiling_data.totalTasks);
    op.Process();
}

