    __aicore__ inline void ScanUnrolled16(const AscendC::LocalTensor<float> &x,
                                         const AscendC::LocalTensor<float> &y,
                                         uint32_t n, float &carry)
    {
        float acc = carry;

        uint32_t i = 0;
        for (; i + 16 <= n; i += 16) {
            float v0  = x(i + 0);
            float v1  = x(i + 1);
            float v2  = x(i + 2);
            float v3  = x(i + 3);
            float v4  = x(i + 4);
            float v5  = x(i + 5);
            float v6  = x(i + 6);
            float v7  = x(i + 7);
            float v8  = x(i + 8);
            float v9  = x(i + 9);
            float v10 = x(i + 10);
            float v11 = x(i + 11);
            float v12 = x(i + 12);
            float v13 = x(i + 13);
            float v14 = x(i + 14);
            float v15 = x(i + 15);

