#include "kernel_operator.h"

class KernelCumsumInclusive {
public:
    static constexpr uint32_t TILE_ELEMS = 4096;
    static constexpr uint32_t BLOCK_DIM = 48;

    __aicore__ inline KernelCumsumInclusive() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t rows, uint32_t cols,
                               uint32_t totalElems, uint32_t rowsPerCore)
    {
        this->rows = rows;
        this->cols = cols;
        this->totalElems = totalElems;
        this->rowsPerCore = rowsPerCore;

        xGm.SetGlobalBuffer((__gm__ float*)x, totalElems);
        yGm.SetGlobalBuffer((__gm__ float*)y, totalElems);

        pipe.InitBuffer(xQueue, 1, TILE_ELEMS * sizeof(float));
        pipe.InitBuffer(yQueue, 1, TILE_ELEMS * sizeof(float));
        pipe.InitBuffer(scanPingBuf, TILE_ELEMS * sizeof(float));
        pipe.InitBuffer(scanPongBuf, TILE_ELEMS * sizeof(float));
        pipe.InitBuffer(shiftedBuf, TILE_ELEMS * sizeof(float));
        pipe.InitBuffer(offsetsBuf, TILE_ELEMS * sizeof(uint32_t));
        eventVToS = pipe.FetchEventID<AscendC::HardEvent::V_S>();
    }

    __aicore__ inline void Process()
    {
        if (rows == 0 || cols == 0) return;

        const uint32_t core = static_cast<uint32_t>(AscendC::GetBlockIdx());
        const uint32_t startRow = (rows * core) / BLOCK_DIM;
        const uint32_t endRow = (rows * (core + 1U)) / BLOCK_DIM;
        if (startRow >= rows) return;
        uint32_t base = startRow * cols;
        for (uint32_t r = startRow; r < endRow; ++r) {
            ProcessRowBase(base);
            base += cols;
        }
    }

private:
    __aicore__ inline void ScanUnrolled16(const AscendC::LocalTensor<float> &x,
                                         const AscendC::LocalTensor<float> &y,
                                         float &carry)
    {
        AscendC::LocalTensor<float> scanPing = scanPingBuf.Get<float>();
        AscendC::LocalTensor<float> scanPong = scanPongBuf.Get<float>();
        AscendC::LocalTensor<float> shifted = shiftedBuf.Get<float>();
        AscendC::LocalTensor<int32_t> offsets = offsetsBuf.Get<int32_t>();
        AscendC::LocalTensor<uint32_t> gatherOffsets = offsets.ReinterpretCast<uint32_t>();

        AscendC::DataCopy(scanPing, x, TILE_ELEMS);
        AscendC::PipeBarrier<PIPE_V>();

        bool pingIsSource = true;
        for (uint32_t stride = 1; stride < TILE_ELEMS; stride <<= 1) {
            AscendC::LocalTensor<float> src = pingIsSource ? scanPing : scanPong;
            AscendC::LocalTensor<float> dst = pingIsSource ? scanPong : scanPing;
            const int32_t byteShift = static_cast<int32_t>(stride * sizeof(float));

            AscendC::ArithProgression(offsets, -byteShift,
                                      static_cast<int32_t>(sizeof(float)),
                                      static_cast<int32_t>(TILE_ELEMS));
            AscendC::Maxs(offsets, offsets, 0, static_cast<int32_t>(TILE_ELEMS));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Gather(shifted, src, gatherOffsets, 0, TILE_ELEMS);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Duplicate(shifted, 0.0f, static_cast<int32_t>(stride));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Add(dst, src, shifted, static_cast<int32_t>(TILE_ELEMS));
            AscendC::PipeBarrier<PIPE_V>();
            pingIsSource = !pingIsSource;
        }

        AscendC::LocalTensor<float> scanResult = pingIsSource ? scanPing : scanPong;
        AscendC::Duplicate(shifted, carry, static_cast<int32_t>(TILE_ELEMS));
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Add(y, scanResult, shifted, static_cast<int32_t>(TILE_ELEMS));
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::SetFlag<AscendC::HardEvent::V_S>(eventVToS);
        AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventVToS);
        carry = y.GetValue(TILE_ELEMS - 1);
    }

    __aicore__ inline void ProcessRowBase(uint32_t base)
    {
        float carry = 0.0f;

        uint32_t c = 0;
        while (c + TILE_ELEMS <= cols) {
            AscendC::LocalTensor<float> xLocal = xQueue.AllocTensor<float>();
            AscendC::DataCopy(xLocal, xGm[base + c], TILE_ELEMS);
            xQueue.EnQue(xLocal);
            xLocal = xQueue.DeQue<float>();

            AscendC::LocalTensor<float> yLocal = yQueue.AllocTensor<float>();
            ScanUnrolled16(xLocal, yLocal, carry);
            xQueue.FreeTensor(xLocal);
            yQueue.EnQue(yLocal);
            yLocal = yQueue.DeQue<float>();
            AscendC::DataCopy(yGm[base + c], yLocal, TILE_ELEMS);
            yQueue.FreeTensor(yLocal);
            c += TILE_ELEMS;
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> xQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> yQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scanPingBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scanPongBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> shiftedBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetsBuf;
    AscendC::TEventID eventVToS = 0;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t rows = 0;
    uint32_t cols = 0;
    uint32_t totalElems = 0;
    uint32_t rowsPerCore = 0;
};

extern "C" __global__ __aicore__ void cumsum_custom(GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelCumsumInclusive op;
    op.Init(x, y, tiling_data.rows, tiling_data.cols, tiling_data.totalElems, tiling_data.rowsPerCore);
    op.Process();
}

