#include "kernel_operator.h"

class KernelCumsumExclusive {
public:
    static constexpr uint32_t TILE_ELEMS = 12272;

    __aicore__ inline KernelCumsumExclusive() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t rows, uint32_t cols,
                               uint32_t rowsPerCore)
    {
        rows_ = rows;
        cols_ = cols;
        rowsPerCore_ = rowsPerCore;

        const uint32_t totalElems = rows_ * cols_;
        xGm_.SetGlobalBuffer((__gm__ float*)x, totalElems);
        yGm_.SetGlobalBuffer((__gm__ float*)y, totalElems);

        pipe_.InitBuffer(inQueue_, 1, TILE_ELEMS * sizeof(float));
        pipe_.InitBuffer(outQueue_, 1, TILE_ELEMS * sizeof(float));
        pipe_.InitBuffer(shiftBuf_, TILE_ELEMS * sizeof(float));
        pipe_.InitBuffer(offsetBuf_, TILE_ELEMS * sizeof(int32_t));
    }

    __aicore__ inline void Process()
    {
        if (rows_ == 0 || cols_ == 0) return;

        const uint32_t core = static_cast<uint32_t>(AscendC::GetBlockIdx());
        const uint32_t startRow = core * rowsPerCore_;
        uint32_t endRow = startRow + rowsPerCore_;
        if (endRow > rows_) endRow = rows_;
        if (startRow >= rows_) return;

        for (uint32_t r = startRow; r < endRow; ++r) {
            ProcessRow(r);
        }
    }

private:
    __aicore__ inline void ProcessRow(uint32_t row)
    {
        const uint32_t base = row * cols_;

        float carry = 0.0f;
        uint32_t c = 0;

        while (c < cols_) {
            uint32_t n = cols_ - c;
            if (n > TILE_ELEMS) n = TILE_ELEMS;

            AscendC::LocalTensor<float> xUb = inQueue_.AllocTensor<float>();
            AscendC::DataCopy(xUb, xGm_[base + c], n);
            inQueue_.EnQue(xUb);
            xUb = inQueue_.DeQue<float>();

            AscendC::LocalTensor<float> yUb = outQueue_.AllocTensor<float>();

            AscendC::LocalTensor<float> shift = shiftBuf_.Get<float>();
            AscendC::LocalTensor<int32_t> offset = offsetBuf_.Get<int32_t>();
            AscendC::LocalTensor<uint32_t> gatherOffset = offset.ReinterpretCast<uint32_t>();

            bool scanInX = true;
            for (uint32_t stride = 1; stride < n; stride <<= 1) {
                const int32_t byteStride = static_cast<int32_t>(stride * sizeof(float));
                AscendC::ArithProgression(offset, -byteStride,
                    static_cast<int32_t>(sizeof(float)), static_cast<int32_t>(n));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Maxs(offset, offset, static_cast<int32_t>(0), static_cast<int32_t>(n));
                AscendC::PipeBarrier<PIPE_V>();
                if (scanInX) {
                    AscendC::Gather(shift, xUb, gatherOffset, 0, n);
                } else {
                    AscendC::Gather(shift, yUb, gatherOffset, 0, n);
                }
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Duplicate(shift, 0.0f, static_cast<int32_t>(stride));
                AscendC::PipeBarrier<PIPE_V>();
                if (scanInX) {
                    AscendC::Add(yUb, xUb, shift, static_cast<int32_t>(n));
                } else {
                    AscendC::Add(xUb, yUb, shift, static_cast<int32_t>(n));
                }
                AscendC::PipeBarrier<PIPE_V>();
                scanInX = !scanInX;
            }

            AscendC::LocalTensor<float> inclusive = scanInX ? xUb : yUb;
            auto eventIdVToS = GetTPipePtr()->FetchEventID(AscendC::HardEvent::V_S);
            AscendC::SetFlag<AscendC::HardEvent::V_S>(eventIdVToS);
            AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventIdVToS);
            const float nextCarry = carry + inclusive.GetValue(n - 1);

            AscendC::ArithProgression(offset, -static_cast<int32_t>(sizeof(float)),
                static_cast<int32_t>(sizeof(float)), static_cast<int32_t>(n));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Maxs(offset, offset, static_cast<int32_t>(0), static_cast<int32_t>(n));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Gather(shift, inclusive, gatherOffset, 0, n);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Duplicate(shift, 0.0f, static_cast<int32_t>(1));
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::LocalTensor<float> carryPlane = offsetBuf_.Get<float>();
            AscendC::Duplicate(carryPlane, carry, static_cast<int32_t>(n));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Add(yUb, shift, carryPlane, static_cast<int32_t>(n));
            carry = nextCarry;

            outQueue_.EnQue(yUb);
            inQueue_.FreeTensor(xUb);

            yUb = outQueue_.DeQue<float>();
            AscendC::DataCopy(yGm_[base + c], yUb, n);
            outQueue_.FreeTensor(yUb);

            c += n;
        }
    }

private:
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> shiftBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBuf_;

    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<float> yGm_;

    uint32_t rows_ = 0;
    uint32_t cols_ = 0;
    uint32_t rowsPerCore_ = 0;
};

