        while (remaining > 0) {
            uint32_t tileStart;
            uint32_t n;
            if (remaining > TILE_ELEMS) {
                n = TILE_ELEMS;
                tileStart = remaining - TILE_ELEMS;
            } else {
                n = remaining;
                tileStart = 0;
            }
