#include "kernel_operator.h"

class KernelCumsumReverse {
public:
    static constexpr uint32_t TILE_ELEMS = 4096;
    static constexpr uint32_t SCAN_STAGES = 12;
    static constexpr uint32_t TILE_BYTES = TILE_ELEMS * sizeof(float);

    __aicore__ inline KernelCumsumReverse() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t rows, uint32_t cols,
                               uint32_t totalElems)
    {
        rows_ = rows;
        cols_ = cols;
        totalElems_ = totalElems;

        xGm_.SetGlobalBuffer((__gm__ float*)x, totalElems_);
        yGm_.SetGlobalBuffer((__gm__ float*)y, totalElems_);

        pipe_.InitBuffer(inputQueue_, 1, TILE_BYTES);
        pipe_.InitBuffer(outputQueue_, 1, TILE_BYTES);
        pipe_.InitBuffer(scanPing_, TILE_BYTES);
        pipe_.InitBuffer(scanPong_, TILE_BYTES);
        pipe_.InitBuffer(shifted_, TILE_BYTES);
        pipe_.InitBuffer(offsets_, TILE_ELEMS * sizeof(int32_t));
        pipe_.InitBuffer(carryPlane_, TILE_BYTES);
    }

    __aicore__ inline void Process()
    {
        if (rows_ == 0 || cols_ == 0) return;

        const uint32_t core = static_cast<uint32_t>(AscendC::GetBlockIdx());
        const uint32_t blockDim = static_cast<uint32_t>(AscendC::GetBlockNum());

        for (uint32_t r = core; r < rows_; r += blockDim) {
            ProcessRow(r);
        }
    }

private:
    __aicore__ inline void ProcessRow(uint32_t row)
    {
        const uint32_t base = row * cols_;

        AscendC::LocalTensor<float> scanPing = scanPing_.Get<float>();
        AscendC::LocalTensor<float> scanPong = scanPong_.Get<float>();
        AscendC::LocalTensor<float> shifted = shifted_.Get<float>();
        AscendC::LocalTensor<int32_t> offsets = offsets_.Get<int32_t>();
        AscendC::LocalTensor<uint32_t> gatherOffsets = offsets.ReinterpretCast<uint32_t>();
        AscendC::LocalTensor<float> carryPlane = carryPlane_.Get<float>();

        AscendC::Duplicate(carryPlane, 0.0f, static_cast<int32_t>(TILE_ELEMS));
        AscendC::PipeBarrier<PIPE_V>();

        for (uint32_t remaining = cols_; remaining > 0; remaining -= TILE_ELEMS) {
            const uint32_t tileStart = remaining - TILE_ELEMS;

            AscendC::LocalTensor<float> input = inputQueue_.AllocTensor<float>();
            AscendC::DataCopy(input, xGm_[base + tileStart], TILE_ELEMS);
            inputQueue_.EnQue(input);
            input = inputQueue_.DeQue<float>();

            AscendC::ArithProgression(offsets, static_cast<int32_t>(TILE_BYTES - sizeof(float)),
                                      static_cast<int32_t>(-sizeof(float)),
                                      static_cast<int32_t>(TILE_ELEMS));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Gather(scanPing, input, gatherOffsets, 0, TILE_ELEMS);
            AscendC::PipeBarrier<PIPE_V>();
            inputQueue_.FreeTensor(input);

            for (uint32_t stage = 0; stage < SCAN_STAGES; ++stage) {
                const uint32_t stride = 1U << stage;
                AscendC::LocalTensor<float> src = (stage & 1U) == 0 ? scanPing : scanPong;
                AscendC::LocalTensor<float> dst = (stage & 1U) == 0 ? scanPong : scanPing;

                AscendC::ArithProgression(offsets, -static_cast<int32_t>(stride * sizeof(float)),
                                          static_cast<int32_t>(sizeof(float)),
                                          static_cast<int32_t>(TILE_ELEMS));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Maxs(offsets, offsets, static_cast<int32_t>(0),
                              static_cast<int32_t>(TILE_ELEMS));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Gather(shifted, src, gatherOffsets, 0, TILE_ELEMS);
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Duplicate(shifted, 0.0f, static_cast<int32_t>(stride));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Add(dst, src, shifted, static_cast<int32_t>(TILE_ELEMS));
                AscendC::PipeBarrier<PIPE_V>();
            }

            AscendC::Add(scanPing, scanPing, carryPlane, static_cast<int32_t>(TILE_ELEMS));
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::ArithProgression(offsets, static_cast<int32_t>(TILE_BYTES - sizeof(float)),
                                      static_cast<int32_t>(-sizeof(float)),
                                      static_cast<int32_t>(TILE_ELEMS));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::LocalTensor<float> output = outputQueue_.AllocTensor<float>();
            AscendC::Gather(output, scanPing, gatherOffsets, 0, TILE_ELEMS);
            AscendC::PipeBarrier<PIPE_V>();
            outputQueue_.EnQue(output);
            output = outputQueue_.DeQue<float>();
            AscendC::DataCopy(yGm_[base + tileStart], output, TILE_ELEMS);
            outputQueue_.FreeTensor(output);

            if (tileStart != 0) {
                AscendC::ArithProgression(offsets,
                                          static_cast<int32_t>(TILE_BYTES - sizeof(float)),
                                          static_cast<int32_t>(0),
                                          static_cast<int32_t>(TILE_ELEMS));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Gather(carryPlane, scanPing, gatherOffsets, 0, TILE_ELEMS);
                AscendC::PipeBarrier<PIPE_V>();
            }
        }
    }

private:
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scanPing_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scanPong_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> shifted_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsets_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> carryPlane_;

    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<float> yGm_;

    uint32_t rows_ = 0;
    uint32_t cols_ = 0;
    uint32_t totalElems_ = 0;
};

