        yBase.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(y));
        gammaBase.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(gamma));
        betaBase.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(beta));

        const uint32_t blockNum = static_cast<uint32_t>(AscendC::GetBlockNum());
        const uint32_t blockIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());

        this->groupStart = blockIdx;
        this->groupStride = blockNum;

        pipe.InitBuffer(xBuf, TILE_ELEMENTS * sizeof(float));
        pipe.InitBuffer(tmpBuf, TILE_ELEMENTS * sizeof(float));
        pipe.InitBuffer(gammaBuf, TILE_ELEMENTS * sizeof(float));
        pipe.InitBuffer(betaBuf, TILE_ELEMENTS * sizeof(float));
        pipe.InitBuffer(scBuf, VECTOR_ALIGN_ELEMENTS * sizeof(float));
        xLocal = xBuf.Get<float>();
        tmpLocal = tmpBuf.Get<float>();
        gammaLocal = gammaBuf.Get<float>();
        betaLocal = betaBuf.Get<float>();
        sc = scBuf.Get<float>();
    }

    __aicore__ inline void Process()
    {
        if (groupStart >= groupsTotal) return;
        if (N == 0 || C == 0 || HW == 0 || G == 0 || groupSize == 0) return;
        if ((C % G) != 0) return;

        for (uint32_t globalGroup = groupStart; globalGroup < groupsTotal; globalGroup += groupStride) {
            ComputeOneGroup(globalGroup);
        }
    }

private:
    __aicore__ inline float InvSqrtFast(float v)
    {
        sc.SetValue(0, v);
        AscendC::Rsqrt<float>(sc, sc, 1);
        return sc.GetValue(0);
    }

    __aicore__ inline uint32_t AlignElements(uint32_t valid) const
    {
        return (valid + VECTOR_ALIGN_ELEMENTS - 1u) & ~(VECTOR_ALIGN_ELEMENTS - 1u);
    }

    __aicore__ inline void CopyIn(const AscendC::LocalTensor<float>& dst,
                                  const AscendC::GlobalTensor<float>& src, uint64_t offset, uint32_t valid)
    {
        const uint32_t copyBytes = valid * static_cast<uint32_t>(sizeof(float));
        const uint32_t aligned = AlignElements(valid);
        const uint8_t rightPad = static_cast<uint8_t>(aligned - valid);
        AscendC::DataCopyExtParams params{1, copyBytes, 0, 0, 0};
        AscendC::DataCopyPadExtParams<float> pad{rightPad != 0, 0, rightPad, 0.0f};
        AscendC::DataCopyPad(dst, src[offset], params, pad);
    }

    __aicore__ inline void CopyOut(const AscendC::GlobalTensor<float>& dst, uint64_t offset,
                                   const AscendC::LocalTensor<float>& src, uint32_t valid)
    {
        const uint32_t copyBytes = valid * static_cast<uint32_t>(sizeof(float));
        AscendC::DataCopyExtParams params{1, copyBytes, 0, 0, 0};
        AscendC::DataCopyPad(dst[offset], src, params);
    }

    template <AscendC::HardEvent event>
    __aicore__ inline void Sync()
    {
        event_t id = static_cast<event_t>(GetTPipePtr()->FetchEventID(event));
        AscendC::SetFlag<event>(id);
        AscendC::WaitFlag<event>(id);
    }

    __aicore__ inline void ComputeOneGroup(uint32_t globalGroup)
    {
        const uint32_t n = globalGroup / G;
        const uint32_t g = globalGroup - n * G;
        const uint32_t cStart = g * groupSize;

        float sum = 0.0f;
        float sumsq = 0.0f;

        const uint64_t groupBase = (static_cast<uint64_t>(n) * C + cStart) * HW;
        const uint32_t reduceCount = groupSize * HW;
        for (uint32_t offset = 0; offset < reduceCount; offset += TILE_ELEMENTS) {
            const uint32_t remain = reduceCount - offset;
            const uint32_t valid = remain < TILE_ELEMENTS ? remain : TILE_ELEMENTS;
            const uint32_t copyBytes = valid * static_cast<uint32_t>(sizeof(float));
            const uint32_t aligned = AlignElements(valid);
            const uint8_t rightPad = static_cast<uint8_t>(aligned - valid);
            AscendC::DataCopyExtParams copyParams{1, copyBytes, 0, 0, 0};
            AscendC::DataCopyPadExtParams<float> padParams{rightPad != 0, 0, rightPad, 0.0f};
            AscendC::DataCopyPad(xLocal, xBase[groupBase + offset], copyParams, padParams);
            Sync<AscendC::HardEvent::MTE2_V>();
            AscendC::ReduceSum(sc, xLocal, tmpLocal, static_cast<int32_t>(valid));
            Sync<AscendC::HardEvent::V_S>();
            sum += sc.GetValue(0);
            AscendC::Mul(tmpLocal, xLocal, xLocal, static_cast<int32_t>(valid));
            AscendC::ReduceSum(sc, tmpLocal, xLocal, static_cast<int32_t>(valid));
            Sync<AscendC::HardEvent::V_S>();
            sumsq += sc.GetValue(0);
            Sync<AscendC::HardEvent::V_MTE2>();
        }

        const float mean = sum * invReduce;
        float var = sumsq * invReduce - mean * mean;
        if (var < 0.0f) var = 0.0f;
        const float invStd = InvSqrtFast(var + eps);

        for (uint32_t channelOffset = 0; channelOffset < groupSize; channelOffset += TILE_ELEMENTS) {
            const uint32_t channelRemain = groupSize - channelOffset;
            const uint32_t channelValid = channelRemain < TILE_ELEMENTS ? channelRemain : TILE_ELEMENTS;
            CopyIn(gammaLocal, gammaBase, cStart + channelOffset, channelValid);
            CopyIn(betaLocal, betaBase, cStart + channelOffset, channelValid);
            Sync<AscendC::HardEvent::MTE2_S>();
            for (uint32_t localChannel = 0; localChannel < channelValid; ++localChannel) {
                const uint32_t c = cStart + channelOffset + localChannel;
                const float gmma = gammaLocal.GetValue(localChannel);
                const float bta = betaLocal.GetValue(localChannel);
                const uint64_t base = (static_cast<uint64_t>(n) * C + c) * HW;
                for (uint32_t offset = 0; offset < HW; offset += TILE_ELEMENTS) {
                    const uint32_t remain = HW - offset;
                    const uint32_t valid = remain < TILE_ELEMENTS ? remain : TILE_ELEMENTS;
                    CopyIn(xLocal, xBase, base + offset, valid);
                    Sync<AscendC::HardEvent::MTE2_V>();
                    AscendC::Adds<float>(xLocal, xLocal, -mean, static_cast<int32_t>(valid));
                    AscendC::Muls<float>(xLocal, xLocal, invStd, static_cast<int32_t>(valid));
                    AscendC::Muls<float>(xLocal, xLocal, gmma, static_cast<int32_t>(valid));
                    AscendC::Adds<float>(xLocal, xLocal, bta, static_cast<int32_t>(valid));
                    Sync<AscendC::HardEvent::V_MTE3>();
                    CopyOut(yBase, base + offset, xLocal, valid);
                    Sync<AscendC::HardEvent::MTE3_MTE2>();
                }
            }
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xBuf, tmpBuf, gammaBuf, betaBuf, scBuf;
    AscendC::LocalTensor<float> xLocal, tmpLocal, gammaLocal, betaLocal, sc;

    AscendC::GlobalTensor<float> xBase, yBase, gammaBase, betaBase;

    uint32_t N = 0, C = 0, HW = 0;
    uint32_t G = 0, groupSize = 0, groupsTotal = 0;
    uint32_t groupStart = 0, groupStride = 1;
    float invReduce = 0.0f;
    float eps = 1e-5f;
};

extern "C" __global__ __aicore__ void group_norm_custom(GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
                                                       GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);

    KernelGroupNormCustom op;
    op.Init(x, gamma, beta, y,
            tiling_data.N, tiling_data.C, tiling_data.HW,
            tiling_data.G, tiling_data.groupSize, tiling_data.groupsTotal,
            tiling_data.invReduce, tiling_data.eps);
    op.Process();
}

