    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> redBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scBuf_;

    AscendC::GlobalTensor<float> xGm_;
