#include "kernel_operator.h"

class KernelMaxPooling1dCustom {
public:
    __aicore__ inline KernelMaxPooling1dCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t n, uint32_t c,
                               uint32_t l_in, uint32_t l_out,
                               uint32_t totalRows, uint32_t blockDim, uint32_t tileOutputs)
    {
        this->n = n;
        this->c = c;
        this->l_in = l_in;
        this->l_out = l_out;
        this->totalRows = totalRows;
        this->blockDim = blockDim;
        this->tileOutputs = tileOutputs;

        xGm.SetGlobalBuffer((__gm__ float*)x);
        yGm.SetGlobalBuffer((__gm__ float*)y);

        constexpr uint32_t kInputBytes = 9824U * static_cast<uint32_t>(sizeof(float));
        constexpr uint32_t kOutputBytes = 9816U * static_cast<uint32_t>(sizeof(float));
        pipe.InitBuffer(inputQueue, 1, kInputBytes);
        pipe.InitBuffer(outputQueue, 1, kOutputBytes);
        pipe.InitBuffer(accumulatorBuf, kOutputBytes);
        pipe.InitBuffer(shiftedTapBuf, kOutputBytes);
        pipe.InitBuffer(gatherOffsetsBuf, kOutputBytes);
    }

    __aicore__ inline void Process()
    {
        const uint32_t bid = static_cast<uint32_t>(AscendC::GetBlockIdx());
        if (bid >= blockDim) {
            return;
        }

        for (uint32_t row = bid; row < totalRows; row += blockDim) {
            for (uint32_t tileStart = 0; tileStart < l_out; tileStart += tileOutputs) {
                const uint32_t validElems = (l_out - tileStart < tileOutputs) ?
                    (l_out - tileStart) : tileOutputs;
                constexpr int64_t kPadding = 4;
                const int64_t logicalBegin = static_cast<int64_t>(tileStart) - kPadding;
                const int64_t logicalEnd = static_cast<int64_t>(tileStart) +
                    static_cast<int64_t>(validElems) + 3;
                const uint32_t leftPad = logicalBegin < 0 ? static_cast<uint32_t>(-logicalBegin) : 0U;
                const uint32_t rightPad = logicalEnd > static_cast<int64_t>(l_in) ?
                    static_cast<uint32_t>(logicalEnd - static_cast<int64_t>(l_in)) : 0U;
                const uint32_t inputBegin = logicalBegin > 0 ? static_cast<uint32_t>(logicalBegin) : 0U;
                const uint32_t validInputElems = validElems + 7U - leftPad - rightPad;
                const uint32_t inputCopyBytes = validInputElems * static_cast<uint32_t>(sizeof(float));

                AscendC::LocalTensor<float> inputLocal = inputQueue.AllocTensor<float>();
                AscendC::DataCopyExtParams inputCopyParams{
                    static_cast<uint16_t>(1), inputCopyBytes,
                    static_cast<uint32_t>(0), static_cast<uint32_t>(0), static_cast<uint32_t>(0)};
                AscendC::DataCopyPadExtParams<float> padParams{
                    true, static_cast<uint8_t>(leftPad), static_cast<uint8_t>(rightPad), -3.402823466e+38f};
                const uint64_t inputGmOffset = static_cast<uint64_t>(row) *
                    static_cast<uint64_t>(l_in) + inputBegin;
                AscendC::DataCopyPad(inputLocal, xGm[inputGmOffset], inputCopyParams, padParams);
                inputQueue.EnQue(inputLocal);

                inputLocal = inputQueue.DeQue<float>();
                AscendC::LocalTensor<float> outputLocal = outputQueue.AllocTensor<float>();
                AscendC::LocalTensor<float> accumulator = accumulatorBuf.Get<float>();
                AscendC::LocalTensor<float> shiftedTap = shiftedTapBuf.Get<float>();
                AscendC::LocalTensor<int32_t> signedOffsets = gatherOffsetsBuf.Get<int32_t>();
                AscendC::LocalTensor<uint32_t> gatherOffsets = signedOffsets.ReinterpretCast<uint32_t>();
                const int32_t count = static_cast<int32_t>(validElems);

                for (uint32_t tap = 0; tap < 8U; ++tap) {
                    const int32_t firstByteOffset =
                        static_cast<int32_t>(tap * static_cast<uint32_t>(sizeof(float)));
                    AscendC::Arange<int32_t>(signedOffsets, firstByteOffset,
                                            static_cast<int32_t>(sizeof(float)), count);
                    if (tap == 0U) {
                        AscendC::Gather(accumulator, inputLocal, gatherOffsets, 0U, validElems);
                    } else {
                        AscendC::Gather(shiftedTap, inputLocal, gatherOffsets, 0U, validElems);
                        if ((tap & 1U) != 0U) {
                            AscendC::Max(outputLocal, accumulator, shiftedTap, count);
                        } else {
                            AscendC::Max(accumulator, outputLocal, shiftedTap, count);
                        }
                    }
                }

                inputQueue.FreeTensor(inputLocal);
                outputQueue.EnQue(outputLocal);
                outputLocal = outputQueue.DeQue<float>();

                const uint32_t outputCopyBytes = validElems * static_cast<uint32_t>(sizeof(float));
                AscendC::DataCopyExtParams outputCopyParams{
                    static_cast<uint16_t>(1), outputCopyBytes,
                    static_cast<uint32_t>(0), static_cast<uint32_t>(0), static_cast<uint32_t>(0)};
                const uint64_t outputGmOffset = static_cast<uint64_t>(row) *
                    static_cast<uint64_t>(l_out) + tileStart;
                AscendC::DataCopyPad(yGm[outputGmOffset], outputLocal, outputCopyParams);
                outputQueue.FreeTensor(outputLocal);
            }
        }
    }

private:
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accumulatorBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> shiftedTapBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gatherOffsetsBuf;

    uint32_t n, c, l_in, l_out;
    uint32_t totalRows, blockDim, tileOutputs;
};

extern "C" __global__ __aicore__ void max_pooling1d_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);

    KernelMaxPooling1dCustom op;
    op.Init(x, y,
            tiling_data.n, tiling_data.c,
            tiling_data.l_in, tiling_data.l_out,
            tiling_data.totalRows, tiling_data.blockDim, tiling_data.tile_outputs);
    op.Process();
}

