#include "kernel_operator.h"

class KernelMaxPooling2dCustom {
public:
    __aicore__ inline KernelMaxPooling2dCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, uint32_t planeCount,
                                uint32_t inputHeight, uint32_t inputWidth,
                                uint32_t outputHeight, uint32_t outputWidth,
                                uint32_t storageStride)
    {
        this->planeCount = planeCount;
        this->inputHeight = inputHeight;
        this->inputWidth = inputWidth;
        this->outputHeight = outputHeight;
        this->outputWidth = outputWidth;
        this->storageStride = storageStride;

        xGm.SetGlobalBuffer((__gm__ float*)x);
        yGm.SetGlobalBuffer((__gm__ float*)y);

        pipe.InitBuffer(inputQueue, 1, PADDED_ROW_BYTES);
        pipe.InitBuffer(outputQueue, 1, ROW_BYTES);
        pipe.InitBuffer(horizontalRingBuffer, RING_ROWS * ROW_BYTES);
        pipe.InitBuffer(accumulatorBuffer, ROW_BYTES);
        pipe.InitBuffer(gatherPlaneBuffer, ROW_BYTES);
        pipe.InitBuffer(offsetBuffer, TAP_COUNT * OFFSET_ROW_BYTES);
        pipe.InitBuffer(compareMaskBuffer, MASK_BYTES);
    }

    __aicore__ inline void MaxPoolChecked(const AscendC::LocalTensor<float>& dst,
                                          const AscendC::LocalTensor<float>& src0,
                                          const AscendC::LocalTensor<float>& src1,
                                          const AscendC::LocalTensor<float>& src2,
                                          const AscendC::LocalTensor<float>& src3,
                                          const AscendC::LocalTensor<float>& accumulator,
                                          const AscendC::LocalTensor<uint8_t>& compareMask)
    {
        MaxPair(dst, src0, src1, compareMask);
        MaxPair(accumulator, dst, src2, compareMask);
        MaxPair(dst, accumulator, src3, compareMask);
    }

    __aicore__ inline void MaxPoolInterior(const AscendC::LocalTensor<float>& dst,
                                           const AscendC::LocalTensor<float>& src0,
                                           const AscendC::LocalTensor<float>& src1,
                                           const AscendC::LocalTensor<float>& src2,
                                           const AscendC::LocalTensor<float>& src3,
                                           const AscendC::LocalTensor<float>& accumulator,
                                           const AscendC::LocalTensor<uint8_t>& compareMask)
    {
        MaxPair(dst, src0, src1, compareMask);
        MaxPair(accumulator, dst, src2, compareMask);
        MaxPair(dst, accumulator, src3, compareMask);
    }

    __aicore__ inline void Process()
    {
        const uint32_t blockIdx = AscendC::GetBlockIdx();
        const uint32_t blockCount = AscendC::GetBlockNum();
        if (blockIdx >= planeCount) {
            return;
        }

        AscendC::LocalTensor<float> ring = horizontalRingBuffer.Get<float>();
        AscendC::LocalTensor<float> accumulator = accumulatorBuffer.Get<float>();
        AscendC::LocalTensor<float> gatherPlane = gatherPlaneBuffer.Get<float>();
        AscendC::LocalTensor<int32_t> signedOffsets = offsetBuffer.Get<int32_t>();
        AscendC::LocalTensor<uint32_t> offsets = offsetBuffer.Get<uint32_t>();
        AscendC::LocalTensor<uint8_t> compareMask = compareMaskBuffer.Get<uint8_t>();

        AscendC::Arange(signedOffsets, static_cast<int32_t>(TAP0_START_BYTES),
                        static_cast<int32_t>(sizeof(float)), static_cast<int32_t>(COMPUTE_ELEMS));
        AscendC::Arange(signedOffsets[COMPUTE_ELEMS], static_cast<int32_t>(TAP1_START_BYTES),
                        static_cast<int32_t>(sizeof(float)), static_cast<int32_t>(COMPUTE_ELEMS));
        AscendC::Arange(signedOffsets[2U * COMPUTE_ELEMS], static_cast<int32_t>(TAP2_START_BYTES),
                        static_cast<int32_t>(sizeof(float)), static_cast<int32_t>(COMPUTE_ELEMS));
        AscendC::Arange(signedOffsets[3U * COMPUTE_ELEMS], static_cast<int32_t>(TAP3_START_BYTES),
                        static_cast<int32_t>(sizeof(float)), static_cast<int32_t>(COMPUTE_ELEMS));
        AscendC::PipeBarrier<PIPE_V>();

        for (uint32_t planeId = blockIdx; planeId < planeCount; planeId += blockCount) {
            AscendC::Duplicate(accumulator, NEGATIVE_INFINITY, COMPUTE_ELEMS);
            const uint64_t inputPlaneBase = static_cast<uint64_t>(planeId) * inputHeight * inputWidth;
            const uint64_t outputPlaneBase = static_cast<uint64_t>(planeId) * outputHeight * outputWidth;

            for (uint32_t inputRow = 0; inputRow < inputHeight; ++inputRow) {
                AscendC::LocalTensor<float> paddedRow = CopyIn(inputPlaneBase +
                    static_cast<uint64_t>(inputRow) * inputWidth);
                AscendC::LocalTensor<float> horizontal = ring[(inputRow & 3U) * storageStride];
                AscendC::Gather(horizontal, paddedRow, offsets, 0U, COMPUTE_ELEMS);
                AscendC::Gather(gatherPlane, paddedRow, offsets[COMPUTE_ELEMS], 0U, COMPUTE_ELEMS);
                AscendC::PipeBarrier<PIPE_V>();
                MaxPair(horizontal, horizontal, gatherPlane, compareMask);
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Gather(gatherPlane, paddedRow, offsets[2U * COMPUTE_ELEMS], 0U, COMPUTE_ELEMS);
                AscendC::PipeBarrier<PIPE_V>();
                MaxPair(accumulator, horizontal, gatherPlane, compareMask);
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Gather(gatherPlane, paddedRow, offsets[3U * COMPUTE_ELEMS], 0U, COMPUTE_ELEMS);
                AscendC::PipeBarrier<PIPE_V>();
                MaxPair(horizontal, accumulator, gatherPlane, compareMask);
                AscendC::PipeBarrier<PIPE_V>();

                if (inputRow >= 2U) {
                    const uint32_t outputRow = inputRow - 2U;
                    AscendC::LocalTensor<float> top = ring[((outputRow - 1U) & 3U) * storageStride];
                    if (outputRow == 0U) {
                        top = paddedRow;
                        AscendC::Duplicate(top, NEGATIVE_INFINITY, COMPUTE_ELEMS);
                    }
                    CopyOutRow(outputPlaneBase, outputRow, top,
                               ring[(outputRow & 3U) * storageStride],
                               ring[((outputRow + 1U) & 3U) * storageStride],
                               ring[((outputRow + 2U) & 3U) * storageStride], compareMask);
                }
                inputQueue.FreeTensor(paddedRow);
            }

            const uint32_t lastOutputRow = outputHeight - 1U;
            AscendC::LocalTensor<float> bottomPadding = inputQueue.AllocTensor<float>();
            AscendC::Duplicate(bottomPadding, NEGATIVE_INFINITY, COMPUTE_ELEMS);
            CopyOutRow(outputPlaneBase, lastOutputRow,
                       ring[((lastOutputRow - 1U) & 3U) * storageStride],
                       ring[(lastOutputRow & 3U) * storageStride],
                       ring[((lastOutputRow + 1U) & 3U) * storageStride],
                       bottomPadding, compareMask);
            inputQueue.FreeTensor(bottomPadding);
        }
    }

private:
    __aicore__ inline void MaxPair(const AscendC::LocalTensor<float>& dst,
                                   const AscendC::LocalTensor<float>& current,
                                   const AscendC::LocalTensor<float>& candidate,
                                   const AscendC::LocalTensor<uint8_t>& compareMask)
    {
        AscendC::Compare(compareMask, candidate, current, AscendC::CMPMODE::GT, COMPUTE_ELEMS);
        AscendC::Select(dst, compareMask, candidate, current,
                        AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, COMPUTE_ELEMS);
    }

    __aicore__ inline AscendC::LocalTensor<float> CopyIn(uint64_t inputRowBase)
    {
        AscendC::LocalTensor<float> paddedRow = inputQueue.AllocTensor<float>();
        const uint32_t copyBytes = inputWidth * static_cast<uint32_t>(sizeof(float));
        AscendC::DataCopyExtParams copyParams{static_cast<uint16_t>(1U), copyBytes, 0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<float> padParams{
            true, static_cast<uint8_t>(PAD_LEFT_ELEMS), static_cast<uint8_t>(PAD_RIGHT_ELEMS),
            NEGATIVE_INFINITY};
        AscendC::DataCopyPad(paddedRow, xGm[inputRowBase], copyParams, padParams);
        inputQueue.EnQue(paddedRow);
        return inputQueue.DeQue<float>();
    }

    __aicore__ inline void CopyOutRow(uint64_t outputPlaneBase, uint32_t outputRow,
                                      const AscendC::LocalTensor<float>& row0,
                                      const AscendC::LocalTensor<float>& row1,
                                      const AscendC::LocalTensor<float>& row2,
                                      const AscendC::LocalTensor<float>& row3,
                                      const AscendC::LocalTensor<uint8_t>& compareMask)
    {
        AscendC::LocalTensor<float> output = outputQueue.AllocTensor<float>();
        AscendC::LocalTensor<float> accumulator = accumulatorBuffer.Get<float>();
        MaxPoolChecked(output, row0, row1, row2, row3, accumulator, compareMask);
        outputQueue.EnQue(output);
        output = outputQueue.DeQue<float>();
        const uint32_t copyBytes = outputWidth * static_cast<uint32_t>(sizeof(float));
        AscendC::DataCopyExtParams copyParams{static_cast<uint16_t>(1U), copyBytes, 0U, 0U, 0U};
        AscendC::DataCopyPad(yGm[outputPlaneBase + static_cast<uint64_t>(outputRow) * outputWidth],
                            output, copyParams);
        outputQueue.FreeTensor(output);
    }

    static constexpr uint32_t COMPUTE_ELEMS = 512U;
    static constexpr uint32_t TAP_COUNT = 4U;
    static constexpr uint32_t RING_ROWS = 4U;
    static constexpr uint32_t PAD_LEFT_ELEMS = 8U;
    static constexpr uint32_t PAD_RIGHT_ELEMS = 8U;
    static constexpr uint32_t PADDED_ROW_ELEMS = PAD_LEFT_ELEMS + COMPUTE_ELEMS + PAD_RIGHT_ELEMS;
    static constexpr uint32_t ROW_BYTES = COMPUTE_ELEMS * static_cast<uint32_t>(sizeof(float));
    static constexpr uint32_t PADDED_ROW_BYTES = PADDED_ROW_ELEMS * static_cast<uint32_t>(sizeof(float));
    static constexpr uint32_t OFFSET_ROW_BYTES = COMPUTE_ELEMS * static_cast<uint32_t>(sizeof(uint32_t));
    static constexpr uint32_t TAP0_START_BYTES = 28U;
    static constexpr uint32_t TAP1_START_BYTES = 32U;
    static constexpr uint32_t TAP2_START_BYTES = 36U;
    static constexpr uint32_t TAP3_START_BYTES = 40U;
    static constexpr uint32_t MASK_BYTES = COMPUTE_ELEMS;
    static constexpr float NEGATIVE_INFINITY = -3.402823466e+38f;

    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> horizontalRingBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accumulatorBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gatherPlaneBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> compareMaskBuffer;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    uint32_t planeCount;
    uint32_t inputHeight;
    uint32_t inputWidth;
    uint32_t outputHeight;
    uint32_t outputWidth;
    uint32_t storageStride;
};

extern "C" __global__ __aicore__ void max_pooling2d_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);

    KernelMaxPooling2dCustom op;
    op.Init(x, y, tiling_data.planeCount, tiling_data.inputHeight,
            tiling_data.inputWidth, tiling_data.outputHeight,
            tiling_data.outputWidth, tiling_data.storageStride);
    op.Process();
}

