#include "kernel_operator.h"

class KernelMaxPooling3dCustom {
public:
    __aicore__ inline KernelMaxPooling3dCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t n, uint32_t c,
                               uint32_t dIn, uint32_t hIn, uint32_t wIn,
                               uint32_t dOut, uint32_t hOut, uint32_t wOut,
                               uint32_t tileD, uint32_t tileH,
                               uint32_t dTiles, uint32_t hTiles,
                               uint32_t totalTasks, uint32_t blockDim)
    {
        this->n = n;
        this->c = c;
        this->dIn = dIn;
        this->hIn = hIn;
        this->wIn = wIn;
        this->dOut = dOut;
        this->hOut = hOut;
        this->wOut = wOut;
        this->tileD = tileD;
        this->tileH = tileH;
        this->dTiles = dTiles;
        this->hTiles = hTiles;
        this->totalTasks = totalTasks;
        this->blockDim = blockDim;

        hwIn = static_cast<uint64_t>(hIn) * wIn;
        dhwIn = static_cast<uint64_t>(dIn) * hwIn;
        hwOut = static_cast<uint64_t>(hOut) * wOut;
        dhwOut = static_cast<uint64_t>(dOut) * hwOut;

        xGm.SetGlobalBuffer((__gm__ float*)x);
        yGm.SetGlobalBuffer((__gm__ float*)y);

        pipe.InitBuffer(inputQueue, 1, INPUT_ALLOC_ELEMS * sizeof(float));
        pipe.InitBuffer(outputQueue, 1, TILE_D * TILE_H * WIDTH_LANES * sizeof(float));
        pipe.InitBuffer(widthBuffer, D_SPAN_MAX * H_SPAN_MAX * WIDTH_LANES * sizeof(float));
        pipe.InitBuffer(heightBuffer, D_SPAN_MAX * TILE_H * WIDTH_LANES * sizeof(float));
        pipe.InitBuffer(offsetBuffer, WIDTH_LANES * sizeof(uint32_t));
        pipe.InitBuffer(gatherBuffer, WIDTH_LANES * sizeof(float));
        pipe.InitBuffer(reduceBuffer, WIDTH_LANES * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        const uint32_t block = static_cast<uint32_t>(AscendC::GetBlockIdx());
        for (uint32_t task = block; task < totalTasks; task += blockDim) {
            ProcessTile(task);
        }
    }

private:
    static constexpr uint32_t TILE_D = 10;
    static constexpr uint32_t TILE_H = 10;
    static constexpr uint32_t WIDTH_LANES = 64;
    static constexpr uint32_t D_SPAN_MAX = 21;
    static constexpr uint32_t H_SPAN_MAX = 21;
    static constexpr uint32_t INPUT_ALLOC_ELEMS = 144;
    static constexpr uint32_t INPUT_VALID_OFFSET = 8;
    static constexpr uint32_t INPUT_PAD_OFFSET = 7;

    __aicore__ inline uint32_t MinU32(uint32_t a, uint32_t b) const
    {
        return a < b ? a : b;
    }

    __aicore__ inline void ProcessTile(uint32_t task)
    {
        uint32_t code = task;
        const uint32_t hTileIndex = code % hTiles;
        code /= hTiles;
        const uint32_t dTileIndex = code % dTiles;
        code /= dTiles;
        const uint32_t ci = code % c;
        const uint32_t ni = code / c;

        const uint32_t odBase = dTileIndex * tileD;
        const uint32_t ohBase = hTileIndex * tileH;
        const uint32_t validD = MinU32(tileD, dOut - odBase);
        const uint32_t validH = MinU32(tileH, hOut - ohBase);
        const int32_t idFirstSigned = static_cast<int32_t>(odBase * 2U) - 1;
        const int32_t ihFirstSigned = static_cast<int32_t>(ohBase * 2U) - 1;
        const uint32_t idFirst = idFirstSigned < 0 ? 0U : static_cast<uint32_t>(idFirstSigned);
        const uint32_t ihFirst = ihFirstSigned < 0 ? 0U : static_cast<uint32_t>(ihFirstSigned);
        const uint32_t idEnd = MinU32(dIn, 2U * (odBase + validD - 1U) + 2U);
        const uint32_t ihEnd = MinU32(hIn, 2U * (ohBase + validH - 1U) + 2U);
        const uint32_t dSpan = idEnd - idFirst;
        const uint32_t hSpan = ihEnd - ihFirst;
        const uint64_t nc = static_cast<uint64_t>(ni) * c + ci;

        AscendC::LocalTensor<float> width = widthBuffer.Get<float>();
        AscendC::LocalTensor<float> height = heightBuffer.Get<float>();
        AscendC::LocalTensor<int32_t> offsetValues = offsetBuffer.Get<int32_t>();
        AscendC::LocalTensor<uint32_t> offsets = offsetValues.ReinterpretCast<uint32_t>();
        AscendC::LocalTensor<float> gathered = gatherBuffer.Get<float>();
        AscendC::LocalTensor<float> reduced = reduceBuffer.Get<float>();

        for (uint32_t ld = 0; ld < dSpan; ++ld) {
            const uint32_t id = idFirst + ld;
            for (uint32_t lh = 0; lh < hSpan; ++lh) {
                const uint32_t ih = ihFirst + lh;
                AscendC::LocalTensor<float> input = inputQueue.AllocTensor<float>();
                const uint64_t gmOffset = nc * dhwIn + static_cast<uint64_t>(id) * hwIn +
                                          static_cast<uint64_t>(ih) * wIn;
                AscendC::DataCopy(input[INPUT_VALID_OFFSET], xGm[gmOffset], wIn);
                inputQueue.EnQue(input);
                input = inputQueue.DeQue<float>();

                AscendC::Duplicate(input, -3.402823466e+38f, static_cast<int32_t>(INPUT_VALID_OFFSET));
                const uint32_t planeOffset = (ld * hSpan + lh) * WIDTH_LANES;
                AscendC::LocalTensor<float> widthPlane = width[planeOffset];
                for (uint32_t tap = 0; tap < 3U; ++tap) {
                    const uint32_t firstByte = (INPUT_PAD_OFFSET + tap) * sizeof(float);
                    AscendC::Arange(offsetValues, static_cast<int32_t>(firstByte),
                                    static_cast<int32_t>(2U * sizeof(float)),
                                    static_cast<int32_t>(WIDTH_LANES));
                    if (tap == 0U) {
                        AscendC::Gather(widthPlane, input, offsets, 0U, WIDTH_LANES);
                    } else if (tap == 1U) {
                        AscendC::Gather(gathered, input, offsets, 0U, WIDTH_LANES);
                        AscendC::Max(widthPlane, widthPlane, gathered, static_cast<int32_t>(WIDTH_LANES));
                    } else {
                        AscendC::Gather(reduced, input, offsets, 0U, WIDTH_LANES);
                        AscendC::Max(widthPlane, widthPlane, reduced, static_cast<int32_t>(WIDTH_LANES));
                    }
                }
                inputQueue.FreeTensor(input);
            }
        }

        for (uint32_t ld = 0; ld < dSpan; ++ld) {
            for (uint32_t ohLocal = 0; ohLocal < validH; ++ohLocal) {
                const uint32_t oh = ohBase + ohLocal;
                const int32_t startSigned = static_cast<int32_t>(oh * 2U) - 1;
                const uint32_t start = startSigned < 0 ? 0U : static_cast<uint32_t>(startSigned);
                const uint32_t end = MinU32(hIn, oh * 2U + 2U);
                const uint32_t firstLocal = start - ihFirst;
                AscendC::LocalTensor<float> dst = height[(ld * validH + ohLocal) * WIDTH_LANES];
                AscendC::LocalTensor<float> src0 = width[(ld * hSpan + firstLocal) * WIDTH_LANES];
                AscendC::LocalTensor<float> src1 = width[(ld * hSpan + firstLocal + 1U) * WIDTH_LANES];
                AscendC::Max(dst, src0, src1, static_cast<int32_t>(WIDTH_LANES));
                for (uint32_t ih = start + 2U; ih < end; ++ih) {
                    AscendC::LocalTensor<float> src = width[(ld * hSpan + (ih - ihFirst)) * WIDTH_LANES];
                    AscendC::Max(dst, dst, src, static_cast<int32_t>(WIDTH_LANES));
                }
            }
        }

        AscendC::LocalTensor<float> output = outputQueue.AllocTensor<float>();
        for (uint32_t odLocal = 0; odLocal < validD; ++odLocal) {
            const uint32_t od = odBase + odLocal;
            const int32_t startSigned = static_cast<int32_t>(od * 2U) - 1;
            const uint32_t start = startSigned < 0 ? 0U : static_cast<uint32_t>(startSigned);
            const uint32_t end = MinU32(dIn, od * 2U + 2U);
            const uint32_t firstLocal = start - idFirst;
            for (uint32_t ohLocal = 0; ohLocal < validH; ++ohLocal) {
                AscendC::LocalTensor<float> dst = output[(odLocal * validH + ohLocal) * WIDTH_LANES];
                AscendC::LocalTensor<float> src0 = height[(firstLocal * validH + ohLocal) * WIDTH_LANES];
                AscendC::LocalTensor<float> src1 = height[((firstLocal + 1U) * validH + ohLocal) * WIDTH_LANES];
                AscendC::Max(dst, src0, src1, static_cast<int32_t>(WIDTH_LANES));
                for (uint32_t id = start + 2U; id < end; ++id) {
                    AscendC::LocalTensor<float> src = height[((id - idFirst) * validH + ohLocal) * WIDTH_LANES];
                    AscendC::Max(dst, dst, src, static_cast<int32_t>(WIDTH_LANES));
                }
            }
        }

        outputQueue.EnQue(output);
        output = outputQueue.DeQue<float>();
        for (uint32_t odLocal = 0; odLocal < validD; ++odLocal) {
            const uint32_t od = odBase + odLocal;
            for (uint32_t ohLocal = 0; ohLocal < validH; ++ohLocal) {
                const uint32_t oh = ohBase + ohLocal;
                const uint64_t gmOffset = nc * dhwOut + static_cast<uint64_t>(od) * hwOut +
                                          static_cast<uint64_t>(oh) * wOut;
                const uint32_t localOffset = (odLocal * validH + ohLocal) * WIDTH_LANES;
                AscendC::DataCopy(yGm[gmOffset], output[localOffset], wOut);
            }
        }
        outputQueue.FreeTensor(output);
    }

    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> widthBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> heightBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gatherBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuffer;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    uint32_t n, c, dIn, hIn, wIn;
    uint32_t dOut, hOut, wOut;
    uint32_t tileD, tileH, dTiles, hTiles, totalTasks, blockDim;
    uint64_t hwIn, dhwIn, hwOut, dhwOut;
};

extern "C" __global__ __aicore__ void max_pooling3d_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tilingData, tiling);
    KernelMaxPooling3dCustom op;
    op.Init(x, y,
            tilingData.n, tilingData.c,
            tilingData.d_in, tilingData.h_in, tilingData.w_in,
            tilingData.d_out, tilingData.h_out, tilingData.w_out,
            tilingData.tileD, tilingData.tileH,
            tilingData.dTiles, tilingData.hTiles,
            tilingData.totalTasks, tilingData.blockDim);
    op.Process();
}

