static inline int64_t OutDimFloor(int64_t in)
{
    constexpr int64_t K = 3, S = 2, P = 1, D = 1;
    return (in + 2LL * P - (K - 1LL) * D - 1LL) / S + 1LL;
}

static ge::graphStatus TilingFunc(gert::TilingContext* context)
