    if (N0 <= 0 || N1 <= 0 || K0 <= 0 || K1 <= 0) {
        return ge::GRAPH_FAILED;
    }
    if (N0 != N1 || K0 != K1 || N1 != K0) {
        return ge::GRAPH_FAILED;
    }

    const int32_t M = N0;
    const int32_t K = N1;
    const int32_t N = K1;
